import {topics,learningReport,animals,cleanEffort,effortReady,effortText} from './learning.mjs';
const H=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={reduced:'줄이기 시작했어요',protected:'피해를 예방했어요',remaining:'아직 남아 있어요'};
export function openLearning({record,storageKey,mode='report',onReplay=()=>{}}){
 document.querySelector('.learning-screen')?.remove();
 const report=learningReport(record.choices,record.repair),dark=Number(record.id.slice(1))>=6;
 const parent=document.querySelector('.cinema'),restoreFocus=document.activeElement;
 if(parent)parent.inert=true;
 const screen=document.createElement('section');screen.className='learning-screen';screen.setAttribute('role','dialog');screen.setAttribute('aria-modal','true');screen.setAttribute('aria-label','다음 봄을 위한 생태 수첩');
 document.body.append(screen);
 const key=storageKey+'-effort-'+record.id+'-'+record.choices.join('-')+(record.repair?'-repair':'');
 let stored;try{stored=JSON.parse(localStorage.getItem(key)||'null');}catch{}
 let draft=cleanEffort(stored?.draft)||cleanEffort({kind:'campaign',topic:report.remaining[0]?.id||'habitat'}),completed=stored?.complete===true&&effortReady(draft),page=0;
 const close=()=>{screen.remove();if(parent?.isConnected)parent.inert=false;if(restoreFocus?.isConnected)restoreFocus.focus();};
 screen.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const nodes=[...screen.querySelectorAll('button:not(:disabled),input,textarea,select,a[href]')].filter(e=>e.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
 const saveDraft=()=>{try{localStorage.setItem(key,JSON.stringify({draft,complete:completed}));return true;}catch{return false;}};
 const shell=(body,footer)=>{screen.innerHTML=`<header class="learning-head"><div><small>${record.id} · 네 계절 뒤의 기록</small><h1>다음 봄을 위한 생태 수첩</h1></div><button id="learning-close" aria-label="수첩 닫기">×</button></header><nav class="learning-tabs" aria-label="수첩 내용"><button id="learning-report" ${mode==='report'?'aria-current="page"':''}>내 선택 돌아보기</button><button id="learning-effort" ${mode!=='report'?'aria-current="page"':''}>${dark?'노력하기':'보전 약속 쓰기'}${completed?' ✓':''}</button></nav><main class="learning-body">${body}</main><footer class="learning-footer">${footer}</footer>`;screen.querySelector('#learning-close').onclick=close;screen.querySelector('#learning-report').onclick=()=>{mode='report';render();};screen.querySelector('#learning-effort').onclick=()=>{mode='effort';render();};screen.querySelector('h1').tabIndex=-1;screen.querySelector('h1').focus();};
 function reportPage(){
  if(page===0){const group=(rs,title,cls)=>`<section class="report-group ${cls}"><h2>${title}</h2>${rs.length?rs.map(r=>{const t=topics.find(t=>t.id===r.id);return `<button class="report-entry" data-topic="${topics.indexOf(t)+1}"><span>${t.icon}</span><div><strong>${t.name}</strong><p>${r.summary}</p></div><b>›</b></button>`;}).join(''):`<p class="report-empty">${cls==='helped'?'이번 선택에서는 피해를 충분히 줄인 분야를 찾지 못했어요. 남은 문제에서 바꿀 방법을 찾아보세요.':'이번 선택에서는 다섯 분야의 피해를 줄이거나 예방했어요. 다음 계절에도 점검과 관리가 필요해요.'}</p>`}</section>`;
   shell(`<div class="report-intro"><h2>내가 줄인 문제, 아직 남은 문제</h2><p>내 선택 → 환경의 변화 → 생물의 변화 → 우리 생활을 차근차근 이어 보세요.</p></div><div class="report-overview">${group(report.helped,'줄이거나 예방한 문제','helped')}${group(report.remaining,'아직 남은 문제','remaining')}</div><p class="report-caveat">${report.repairNote||'좋은 선택도 한 번으로 끝나지 않아요. 이 수첩은 이야기 속 선택을 돌아보는 기록이에요.'}</p>`,`<small>1 / 6 · 한 분야를 눌러도 자세히 볼 수 있어요.</small><button class="primary" id="report-next">토양오염부터 알아보기 →</button>`);
  }else{
   const t=topics[page-1],r=report.results[page-1];
   shell(`<section class="knowledge-title"><span>${t.icon}</span><div><small>생태계에 미친 영향</small><h2>${t.name}</h2><p>${t.definition}</p></div><b class="learning-badge ${r.level}">${labels[r.level]}</b></section><div class="knowledge-grid"><section class="concept-card"><h3>어떤 활동에서 생길까요?</h3><p>${t.example}</p><h3>이번 마을에서는</h3><p>${r.summary}</p>${r.extra?`<p class="concept-extra">${r.extra}</p>`:''}</section><section class="cause-card"><h3>생물에게, 그리고 우리에게</h3><ol>${r.chain.map((s,i)=>`<li><small>${i+1} · ${['내 선택','환경','생물','사람'][i]}</small><p>${s}</p></li>`).join('')}</ol></section></div><section class="cooperate-card"><p><strong>내가 할 수 있는 일</strong>${t.me}</p><p><strong>사회·국가가 함께 할 일</strong>${t.together}</p></section>`,`<button id="report-prev">← 앞장</button><small>${page+1} / 6</small><button class="primary" id="report-next">${page===5?(dark?'노력하기 →':'보전 약속 쓰기 →'):'다음 장 →'}</button>`);
  }
  screen.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.topic);render();});
  const prev=screen.querySelector('#report-prev');if(prev)prev.onclick=()=>{page--;render();};
  screen.querySelector('#report-next').onclick=()=>{if(page===5)mode='effort';else page++;render();};
 }
 function effortPage(){
  const t=topics.find(t=>t.id===draft.topic),a=animals.find(a=>a.id===draft.animal),letter=draft.kind==='letter';
  shell(`<div class="effort-intro"><h2>다음 봄을 위해 어떤 노력을 할까요?</h2><p>글을 쓰면 이전 피해가 없어지지는 않아요. 내가 할 일과 함께할 사람을 정해 실천을 시작해요.</p></div><div class="effort-switch"><button data-kind="campaign" aria-pressed="${!letter}">📣 캠페인 문구 만들기</button><button data-kind="letter" aria-pressed="${letter}">✉ 멸종위기 동물에게 편지</button></div><div class="effort-grid"><aside class="effort-guide">${letter?`<label>편지를 받을 실제 동물<select id="effort-animal">${animals.map(an=>`<option value="${an.id}" ${a.id===an.id?'selected':''}>${an.name}</option>`).join('')}</select></label><div class="animal-profile"><span>${a.icon}</span><h3>${a.name}</h3><small>${a.grade}</small><p>${a.home}</p><p>${a.risk}</p></div><p>${a.action}</p><a href="${a.source}" target="_blank" rel="noopener noreferrer">국립생태원에서 더 알아보기 ↗</a>`:`<label>알리고 싶은 문제<select id="effort-topic">${topics.map(tp=>`<option value="${tp.id}" ${t.id===tp.id?'selected':''}>${tp.name}</option>`).join('')}</select></label><div class="animal-profile"><span>${t.icon}</span><h3>${t.name}</h3><p>${report.results.find(r=>r.id===t.id).summary}</p></div><p>${t.me}</p><small>예시: “한 번 쓰고 버린 컵, 다음 축제에는 다시 쓰는 컵으로!” 그대로 베끼기보다 내 말을 담아 보세요.</small>`}</aside><form id="effort-form" class="effort-form"><label>${letter?`${a.name}에게 하고 싶은 말`:'함께 실천하도록 알리는 문구'}<textarea name="message" maxlength="260" rows="2" placeholder="${letter?'네가 살아가는 곳을 생각하며 써 보세요.':'무엇을 바꾸자고 알리고 싶나요?'}">${H(draft.message)}</textarea></label><label>왜 이 노력이 필요한가요?<input name="reason" maxlength="120" value="${H(draft.reason)}" placeholder="생물과 우리 생활에 주는 영향을 떠올려 보세요."></label><label>내가 할 수 있는 구체적인 일<input name="action" maxlength="120" value="${H(draft.action)}" placeholder="예: 다음 소풍부터 다회용 물병을 가져갈 거예요."></label><div class="effort-pair"><label>함께할 사람·기관<input name="partner" maxlength="120" value="${H(draft.partner)}" placeholder="예: 친구들, 선생님, 마을 담당자"></label><label>언제부터 할까요?<input name="when" maxlength="120" value="${H(draft.when)}" placeholder="예: 이번 주 금요일부터"></label></div><p id="effort-status" role="status">다섯 칸에 내 생각을 담으면 실천 카드로 남길 수 있어요.</p></form></div>`,`<small>이 글은 이 기기에만 저장돼요. 완성한 카드를 그림으로 받을 수 있어요.</small><button class="primary" id="effort-complete" ${effortReady(draft)?'':'disabled'}>실천 카드 남기기 →</button>`);
  screen.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{draft.kind=b.dataset.kind;completed=false;saveDraft();render();});
  for(const field of ['animal','topic']){const select=screen.querySelector('#effort-'+field);if(select)select.onchange=()=>{draft[field]=select.value;completed=false;saveDraft();render();};}
  screen.querySelector('#effort-form').onsubmit=e=>e.preventDefault();
  screen.querySelectorAll('#effort-form input,#effort-form textarea').forEach(el=>el.oninput=()=>{draft[el.name]=el.value;completed=false;const saved=saveDraft();screen.querySelector('#effort-complete').disabled=!effortReady(draft);screen.querySelector('#effort-status').textContent=saved?(effortReady(draft)?'문구와 까닭, 행동, 함께할 사람, 시작할 때를 담았어요.':'다섯 칸을 모두 채워 보세요. 입력한 글은 이 기기에 보관돼요.'):'기기 저장 공간이 부족해요. 완성 후 그림으로 받아 두세요.';});
  screen.querySelector('#effort-complete').onclick=()=>{if(!effortReady(draft))return;completed=true;saveDraft();mode='card';render();};
 }
 function cardPage(){const letter=draft.kind==='letter',a=animals.find(a=>a.id===draft.animal),t=topics.find(t=>t.id===draft.topic);
  shell(`<article class="effort-card"><small>초록마을 · 다음 봄을 위한 나의 노력</small><div class="card-emblem">${letter?a.icon:t.icon}</div><h2>${letter?a.name+'에게 보내는 편지':t.name+' 보전 캠페인'}</h2><p class="card-message">${H(draft.message)}</p><dl><div><dt>노력이 필요한 까닭</dt><dd>${H(draft.reason)}</dd></div><div><dt>내가 할 일</dt><dd>${H(draft.action)}</dd></div><div><dt>함께할 사람·기관</dt><dd>${H(draft.partner)}</dd></div><div><dt>시작할 때</dt><dd>${H(draft.when)}</dd></div></dl><p class="card-note">실천을 준비했어요. 친구와 이 카드를 읽고, 생활에서 약속을 이어 가세요.<br>이전 엔딩과 피해 기록은 그대로 남아요.</p></article>`,`<button id="effort-edit">글 다듬기</button><button id="effort-download">그림으로 받기</button><button class="primary" id="learning-replay">다른 선택으로 모험하기 →</button>`);
  screen.querySelector('#effort-edit').onclick=()=>{mode='effort';render();};screen.querySelector('#effort-download').onclick=()=>downloadCard(draft);screen.querySelector('#learning-replay').onclick=()=>{close();onReplay();};
 }
 function render(){if(mode==='report')reportPage();else if(mode==='card'&&effortReady(draft))cardPage();else effortPage();}
 if(mode==='effort'&&completed)mode='card';render();return close;
}
export function downloadCard(draft){
 const text=effortText(draft),canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1400;
 const ctx=canvas.getContext('2d');ctx.font='26px "Malgun Gothic", sans-serif';
 const lines=[];for(const paragraph of text.split('\n')){let line='';for(const c of paragraph){if(ctx.measureText(line+c).width>820){lines.push(line);line=c;}else line+=c;}lines.push(line);}
 canvas.height=Math.max(700,200+lines.length*45+100);ctx.fillStyle='#f8f0d7';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#91aa70';ctx.lineWidth=5;ctx.strokeRect(35,35,930,canvas.height-70);ctx.fillStyle='#365345';ctx.font='22px "Malgun Gothic", sans-serif';ctx.fillText('초록마을 · 다음 봄을 위한 나의 노력',90,100);ctx.font='26px "Malgun Gothic", sans-serif';lines.forEach((line,i)=>ctx.fillText(line,90,175+i*45));ctx.font='18px "Malgun Gothic", sans-serif';ctx.fillText('친구와 함께 읽고 생활에서 실천해요.',90,canvas.height-65);
 canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=draft.kind==='letter'?'초록마을_생물에게_보내는_편지.png':'초록마을_보전_캠페인.png';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);},'image/png');
}
